        childMemberIds.forEach(id => {
            const m = nodes.find(n => n.id === id);
            if(m) scaleSmartGroupMemberToZoom(group, m, zoom);
        });
        rerouteSmartConnections(child.id, group.id);
        nodes = nodes.filter(n => n.id !== child.id);
