        if(!menu || !menu.dataset.smartToolLazy || menu.dataset.smartToolFilled === '1') return;
        const builder = smartToolLazyMenuBuilders.get(menu.dataset.smartToolLazy);
        if(!builder) return;
        menu.innerHTML = builder();
        menu.dataset.smartToolFilled = '1';
