        const firstRect = items[0].getBoundingClientRect();
        const gap = items.length > 1 ? Math.abs(items[1].getBoundingClientRect().left - firstRect.right) : 5;
        let pinned = null;
        let pinnedRect = null;
        let pinnedGrowth = 0;
        let pinnedBefore = 0;
        let growthBefore = 0;
